import json, re, sys, urllib.request, datetime
from playwright.sync_api import sync_playwright
BASE='http://localhost:8099'; GAS='https://script.google.com/macros/s/TEST/exec'
errors=[]; res=[]
def ok(c,m): res.append(bool(c)); print(('  ✔ ' if c else '  ✘ FAIL: ')+m)
def forward(route, request):
    url=request.url.replace(GAS, BASE+'/exec')
    req=urllib.request.Request(url, data=request.post_data.encode() if request.post_data else None, method=request.method)
    body=urllib.request.urlopen(req).read(); route.fulfill(status=200, body=body, headers={'Access-Control-Allow-Origin':'*','Content-Type':'application/json'})
def api(action, **d):
    return json.load(urllib.request.urlopen(urllib.request.Request(BASE+'/exec', data=json.dumps({'action':action, **d}).encode(), method='POST')))
tomorrow=(datetime.date.today()+datetime.timedelta(days=1)).isoformat()
# seed a customer order + enquiry through the public API
o=api('createOrder', requestId='seed-order-0001', customerName='Seed Customer', phone='9123456789', fulfilment='DELIVERY', address='House 5, Main Road, Labdaha', paymentMethod='COD', date=tomorrow, time='12:00', items=[{'productId':'P3','grams':1500}])
ok(o['ok'],'seed order created '+str(o.get('data',{}).get('orderId')))
oid=o['data']['orderId']
e=api('createEnquiry', requestId='seed-enq-00001', customerName='Hotel Grand', phone='9811122233', eventDate=tomorrow, eventLocation='Hotel Grand Labdaha', quantityKg=50, products=['Boneless'])
eid=e['data']['enquiryId']
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1280,'height':800}); ctx.set_default_timeout(15000)
    ctx.route(re.compile(r'https://script\.google\.com/.*'), forward)
    ctx.route('**/assets/js/config.js', lambda r: r.fulfill(body="window.NC_CONFIG={API_URL:'%s',STATUS_REFRESH_MS:30000,CATALOG_CACHE_MS:45000};"%GAS, content_type='text/javascript'))
    ctx.route(re.compile(r'https://cdnjs\.cloudflare\.com/.*chart.*'), lambda r: r.fulfill(body="window.Chart=class{constructor(c,cfg){(window.__charts=window.__charts||[]).push(cfg)}destroy(){}};", content_type='text/javascript'))
    ctx.route(re.compile(r'https://fonts.*'), lambda r: r.abort())
    pg=ctx.new_page(); pg.on('console', lambda m: errors.append(m.text) if m.type=='error' else None); pg.on('pageerror', lambda e: errors.append(str(e)))
    print('Login'); pg.goto(BASE+'/admin.html'); pg.wait_for_selector('#login:not([hidden])')
    ok(pg.locator('#app').is_hidden(),'admin hidden until login')
    pg.fill('#u','owner'); pg.fill('#p','wrong-password-1'); pg.click('#lgo'); pg.wait_for_selector('#lmsg .alert'); ok('Incorrect' in pg.inner_text('#lmsg'),'wrong password rejected')
    pg.fill('#p','Correct-Horse-9'); pg.click('#lgo'); pg.wait_for_selector('#app:not([hidden])')
    ok('owner' in pg.inner_text('#who'),'signed in as owner'); ok('Correct-Horse' not in pg.content(),'password not left in DOM')
    pg.wait_for_function("document.getElementById('sync').innerText.startsWith('Synced')"); ok(True,'sync indicator shows synced')
    print('Dashboard'); pg.wait_for_selector('.kpis'); 
    V=lambda: pg.inner_text('#view').lower(); ok("today's sales" in V(),'dashboard KPIs render'); ok('est. gross profit' in V() and 'add product costs' in V(),'profit hidden until costs configured')
    pg.wait_for_function('window.__charts && window.__charts.length>=8'); ok(len(pg.evaluate('window.__charts'))==8,'8 chart configs built')
    ok('pending (received)' in V(),'pending count shown'); pg.screenshot(path='/tmp/shots/admin_dash.png')
    print('Orders'); pg.click('#nav a[data-p=orders]'); pg.wait_for_selector('table.t [data-o]'); ok(oid in pg.inner_text('#view'),'order listed')
    pg.fill('#oq','9123'); pg.click('#ogo'); pg.wait_for_selector('table.t [data-o]'); ok(pg.locator('[data-o]').count()==1,'search by phone')
    pg.click('[data-o]'); pg.wait_for_selector('.modal [data-st]')
    ok('Out for delivery' in pg.inner_text('.modal') and 'Ready for pickup' not in pg.inner_text('.modal'),'delivery order offers dispatch, not pickup')
    pg.click('.modal [data-st=CONFIRMED]'); pg.wait_for_selector('.modal [data-st=PREPARING]'); pg.wait_for_function("(document.querySelector('.modal h3')||{innerText:''}).innerText.includes('Confirmed')"); ok(True,'confirmed via UI')
    pg.click('.modal [data-st=PREPARING]'); pg.wait_for_selector('.modal [data-st=OUT_FOR_DELIVERY]')
    pg.fill('.modal #pa','50'); pg.click('.modal [data-pay]'); pg.wait_for_selector('.modal :text("Partly paid"), .modal .tag.PARTIAL'); ok(pg.locator('.modal .tag.PARTIAL').count()>=1,'partial payment recorded (not marked paid)')
    pg.click('.modal [data-st=OUT_FOR_DELIVERY]'); pg.wait_for_selector('.modal [data-st=DELIVERED]')
    pg.wait_for_selector('.modal .timeline li >> nth=3'); n=pg.locator('.modal .timeline li').count(); ok(n==4,'history has 4 entries (%d)'%n)
    pg.click('.modal [data-cancel]'); pg.wait_for_selector('.modal-bg >> nth=1'); pg.click('.modal-bg >> nth=1 >> [data-x="1"]'); ok(pg.locator('#cm-i').count()==1,'cancel requires reason (still open when empty)')
    pg.fill('#cm-i','Customer unreachable'); pg.click('[data-x="1"]'); pg.wait_for_function("(document.querySelector('.modal h3')||{innerText:''}).innerText.includes('Cancelled')"); ok(True,'cancelled with reason')
    pg.click('.modal [data-close] >> nth=0')
    print('Products'); pg.click('#nav a[data-p=products]'); pg.wait_for_selector('[data-ed]')
    pg.click('[data-ed]:first-of-type >> nth=0'); pg.wait_for_selector('#pn'); pg.fill('#pp','180'); pg.fill('#pco','120'); pg.click('.modal [data-save]'); pg.wait_for_selector('.toast.ok')
    cat=json.load(urllib.request.urlopen(BASE+'/exec?action=catalog'))['data']; ok(cat['products'][0]['pricePerKg']==180,'price change visible on public catalogue immediately')
    pg.wait_for_selector('[data-av]'); pg.uncheck('[data-av="P2"]'); pg.wait_for_function("document.querySelector('.toast.ok')"); cat=json.load(urllib.request.urlopen(BASE+'/exec?action=catalog'))['data']; ok([x for x in cat['products'] if x['id']=='P2'][0]['available']==False,'availability toggle reaches public site')
    pg.click('#padd'); pg.wait_for_selector('#pn'); pg.fill('#pn','Chicken Lollipop'); pg.fill('#pp','260'); pg.click('.modal [data-save]'); pg.wait_for_selector('text=Chicken Lollipop'); ok(True,'new product added')
    print('Enquiries'); pg.click('#nav a[data-p=enquiries]'); pg.wait_for_selector('[data-e]'); pg.click('[data-e]'); pg.wait_for_selector('#eq')
    pg.select_option('#eq','Confirmed'); pg.fill('#eqa','9500'); pg.click('.modal [data-save]'); pg.wait_for_selector('.toast.ok')
    pg.click('[data-e]'); pg.wait_for_selector('[data-conv]'); pg.click('[data-conv]'); pg.click('.modal-bg >> nth=1 >> [data-x="1"]'); pg.wait_for_selector('.toast:has-text("Created order")'); ok(True,'enquiry converted to order via UI')
    print('Shop status'); pg.click('#nav a[data-p=shop]'); pg.wait_for_selector('[data-set=CLOSED]'); pg.fill('#sm','Closed for prayers'); pg.select_option('#soh','2'); pg.click('[data-set=CLOSED]'); pg.click('.modal-bg [data-x="1"]'); pg.wait_for_selector('.toast:has-text("CLOSED")')
    st=json.load(urllib.request.urlopen(BASE+'/exec?action=status'))['data']; ok(st['state']=='CLOSED' and st['message']=='Closed for prayers','public status closed with message')
    pg2=ctx.new_page(); pg2.goto(BASE+'/index.html'); pg2.wait_for_selector('.hdr [data-status-pill]:has-text("CLOSED")'); ok('Closed for prayers' in pg2.inner_text('.status-card'),'public site shows CLOSED + message'); pg2.close()
    pg.click('[data-set=AUTO]'); pg.wait_for_selector('.toast.ok'); pg.wait_for_selector('#hrs input[data-f=open] >> nth=6')
    ok(pg.locator('#hrs input[data-f=open]').count()>=7,'owner hours editor present')
    print('Settings'); pg.click('#nav a[data-p=settings]'); pg.wait_for_selector('#s_Phone'); pg.fill('#s_Phone','12345'); pg.click('#ssave'); pg.wait_for_selector('.toast.err'); ok(True,'invalid phone rejected')
    pg.fill('#s_Phone','9876501234'); pg.select_option('#s_DemoMode','FALSE'); pg.click('#ssave'); pg.wait_for_selector('.toast.ok:has-text("Saved")')
    cat=json.load(urllib.request.urlopen(BASE+'/exec?action=catalog'))['data']; ok(cat['settings']['Phone']=='9876501234','phone setting live')
    print('Inventory'); pg.click('#nav a[data-p=inventory]'); pg.wait_for_selector('#iadd'); pg.select_option('#ip','P1'); pg.fill('#iq','12'); pg.click('#iadd'); pg.wait_for_selector('.toast.ok'); pg.wait_for_selector('table.t td:has-text("12")'); ok(True,'stock purchase recorded')
    print('Reports'); pg.click('#nav a[data-p=reports]'); pg.wait_for_selector('#rrun'); pg.select_option('#rt','product_sales'); pg.click('#rrun'); pg.wait_for_selector('#rout table.t')
    with pg.expect_download() as dl: pg.click('#rcsv')
    csv=open(dl.value.path(),encoding='utf-8-sig').read(); ok(csv.startswith('"Product"') and 'Revenue' in csv,'CSV export downloads'); 
    print('Users & audit'); pg.click('#nav a[data-p=users]'); pg.wait_for_selector('#uadd'); pg.click('#uadd'); pg.fill('#uu','staff1'); pg.fill('#upw','StaffPass-12345'); pg.click('.modal [data-save]'); pg.wait_for_selector('.toast.ok')
    pg.click('#nav a[data-p=audit]'); pg.wait_for_selector('#aq'); ok('PRICE_CHANGE' in pg.inner_text('#view') and 'ORDER_STATUS' in pg.inner_text('#view') and 'SHOP_STATUS' in pg.inner_text('#view'),'audit log shows price/order/status changes')
    print('Staff role'); pg.click('#logout'); pg.wait_for_selector('#login:not([hidden])'); pg.fill('#u','staff1'); pg.fill('#p','StaffPass-12345'); pg.click('#lgo'); pg.wait_for_selector('#app:not([hidden])')
    ok(pg.locator('#nav a[data-p=users]').count()==0 and pg.locator('#nav a[data-p=settings]').count()==0,'staff does not see owner pages')
    pg.click('#nav a[data-p=products]'); pg.wait_for_selector('[data-av]'); ok(pg.locator('[data-ed]').count()==0,'staff cannot edit products in UI')
    pg.evaluate("location.hash='#/users'"); pg.wait_for_selector('.kpis'); ok(True,'direct URL to owner page falls back to dashboard')
    print('Session expiry'); tok=json.loads(pg.evaluate("sessionStorage.getItem('nc_admin_session')"))['token']
    urllib.request.urlopen(BASE+'/__admin_clock?ms='+str(7*3600*1000)); pg.click('#refresh'); pg.wait_for_selector('#login:not([hidden])'); ok('expired' in pg.inner_text('#lmsg').lower(),'expired session → login screen'); urllib.request.urlopen(BASE+'/__admin_clock?ms=0')
    ok(pg.evaluate("sessionStorage.getItem('nc_admin_session')") is None,'token removed from storage')
    pg.set_viewport_size({'width':390,'height':844}); b.close()
real=[x for x in errors if 'Failed to load resource' not in x and 'ERR_FAILED' not in x and '401' not in x]
ok(not real,'no unexpected JS console errors: '+str(real[:3]))
print('RESULT', sum(res),'/',len(res)); sys.exit(0 if all(res) else 1)
